async(page)=>{
 const base='http://127.0.0.1:5173/',browser=page.context().browser(),checks=[],metrics=[];const check=(v,m)=>{if(!v)throw Error(m);checks.push(m)},cloud=/tcloudbasegateway\.com|tcb-api\.tencentcloudapi\.com/
 for(const mobile of [false,true]){const context=await browser.newContext({viewport:mobile?{width:390,height:844}:{width:1440,height:900},...(mobile?{isMobile:true,hasTouch:true,userAgent:'Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36 MicroMessenger/8.0.50'}:{})}),p=await context.newPage(),requests=[],sdkRequests=[],errors=[];p.on('request',r=>{if(/index\\.esm-|@cloudbase.*js-sdk/.test(r.url()))sdkRequests.push(r.url());if(cloud.test(r.url()))requests.push(new URL(r.url()).pathname)});p.on('pageerror',e=>errors.push(e.message));await p.route(cloud,r=>r.abort());try{const started=Date.now();await p.goto(base+'?first-entry='+Date.now()+'-'+mobile);await p.getByRole('heading',{name:'注册网页账号',exact:true}).waitFor({timeout:15000});metrics.push({mode:mobile?'simulated-wechat-android':'desktop',milliseconds:Date.now()-started});check(true,'全新'+(mobile?'微信UA模拟':'桌面')+'阻断云端仍显示注册页');check(requests.length===0,'首次注册入口不发起匿名登录和云数据库请求 '+mobile);check(sdkRequests.length===0,'注册首屏不下载大型认证SDK '+mobile);await p.getByRole('button',{name:'注册并验证邮箱',exact:true}).click();check(await p.locator('input:invalid').count()>=2,'缺账号密码不进入注册 '+mobile);check(requests.length===0,'空注册表单没有发送请求 '+mobile);await p.getByRole('button',{name:'已有账号，去登录',exact:true}).click();check(await p.getByRole('heading',{name:'登录小食云记',exact:true}).isVisible(),'新用户可切换已有账号登录 '+mobile);check(!errors.length,'首次入口无运行时错误 '+mobile)}finally{await context.close()}}
 const context=await browser.newContext({viewport:{width:390,height:844}}),p=await context.newPage();try{await p.route(url=>/\/src\/main\.tsx$/.test(url.pathname)||/\/assets\/index-[^/]+\.js$/.test(url.pathname),r=>r.abort());await p.goto(base+'?script-failure='+Date.now());await p.getByRole('button',{name:'重新加载',exact:true}).waitFor({timeout:15000});check((await p.locator('body').innerText()).includes('页面资源加载较慢'),'脚本下载失败显示可理解的静态提示');check(await p.getByRole('button',{name:'重新加载',exact:true}).isVisible(),'资源下载失败有可用重试按钮而非永久白屏')}finally{await context.close()}
 return {base,checks,metrics,cloudBlocked:true,realWeChatDevice:false}
}
